(function(api){const fs=api.fs,appPath=api.basePath;let screen=api.screen===undefined?0:api.screen,menuSelection=api.menuSelection||0,ante=api.ante===undefined?50:api.ante,funds=api.funds===undefined?500:api.funds,opponent=api.opponent||"RINGO",demoModule=0,resultsModule=0,soundModule=0,resultsStartTimer=0,knob1Attached=0,knob2Attached=0,removed=0,resultOutcome=api.resultOutcome||"DRAW",resultDelta=api.resultDelta||0;function drawHeader(title){h.clear().setColor(3).setFontMonofonto16().setFontAlign(0,-1).drawString(title,240,10).drawLine(18,34,462,34).setFontAlign(-1,-1)}function menuRowY(row){if(screen===3)return 244+(row-2)*36;return(screen===0?116:92)+row*36}function drawMenuRow(text,row,selected){const y=menuRowY(row);h.setColor(3).drawString(text,42,y);if(selected)h.drawRect(28,y-5,452,y+23)}function drawMainMenu(){if(menuSelection<0||menuSelection>4)menuSelection=0;drawHeader("CARAVAN");h.drawString("Fallout: New Vegas Card Game",42,48).drawString("Opponent: "+opponent,42,68).drawLine(42,96,438,96);drawMenuRow("Play Caravan",0,menuSelection===0);drawMenuRow("Demo / Tutorial",1,menuSelection===1);drawMenuRow("Rules / Controls",2,menuSelection===2);drawMenuRow("Volume Adjustment",3,menuSelection===3);drawMenuRow("< Back",4,menuSelection===4)}function drawBetMenu(){if(menuSelection<0||menuSelection>3)menuSelection=0;drawHeader("CARAVAN - BET");h.drawRect(22,48,458,138).drawString(opponent+"'s Current Ante: "+ante,38,60).drawString("Your Current Ante: "+ante,38,86).drawString("Your Total Funds: "+funds,38,112);drawMenuRow("Auto-Match",2,menuSelection===0);drawMenuRow("Raise",3,menuSelection===1);drawMenuRow("Accept",4,menuSelection===2);drawMenuRow("Exit",5,menuSelection===3)}function drawDeckMenu(){if(menuSelection<0||menuSelection>1)menuSelection=0;drawHeader("CARAVAN - BUILD DECK");h.drawRect(22,48,458,126).drawString("Cards in Deck: 54",38,62).drawString("Total Cards: 54",38,88).drawString("Caravan Deck",326,62);drawMenuRow("Play Caravan",3,menuSelection===0);drawMenuRow("< Back",4,menuSelection===1)}function drawRules(){drawHeader("CARAVAN - CONTROLS");h.setFont("6x8",2).drawString("LEFT WHEEL",30,52).drawString("Turn: choose caravan",50,72).drawString("Press: open/confirm card action",50,90).drawString("RIGHT WHEEL",30,122).drawString("Turn: scroll cards / action menu",50,142).drawString("GOAL",30,176).drawString("Build each caravan to 21-26.",50,196).drawString("Win at least 2 of 3 sold caravans.",50,214);drawMenuRow("< Back",5,1)}function drawResultFallback(){h.setColor(3).setFont("6x8",2).setFontAlign(0,-1);if(resultOutcome==="PLAYER"){h.drawString("YOU WIN",240,56).drawString("YOU WIN",241,56)}else if(resultOutcome==="CPU"){h.drawString(opponent+" WINS",240,46).drawString(opponent+" WINS",241,46).drawString("YOU LOSE",240,66).drawString("YOU LOSE",241,66)}else{h.drawString("DRAW",240,56).drawString("DRAW",241,56)}h.setFontAlign(-1,-1)}function drawResults(){if(menuSelection<0||menuSelection>1)menuSelection=0;drawHeader("CARAVAN - RESULTS");drawResultFallback();drawMenuRow("Rematch",2,menuSelection===0);drawMenuRow("< Back",3,menuSelection===1)}function menuRowForSelection(selection){if(screen===0)return selection;if(screen===1)return selection+2;if(screen===2)return selection+3;if(screen===3)return selection+2;return 5}function menuTextForSelection(selection){if(screen===0)return selection===0?"Play Caravan":selection===1?"Demo / Tutorial":selection===2?"Rules / Controls":selection===3?"Volume Adjustment":"< Back";if(screen===1)return selection===0?"Auto-Match":selection===1?"Raise":selection===2?"Accept":"Exit";if(screen===2)return selection===0?"Play Caravan":"< Back";if(screen===3)return selection===0?"Rematch":"< Back";return"< Back"}function redrawMenuSelection(previousSelection){let row,y;row=menuRowForSelection(previousSelection);y=menuRowY(row);h.clearRect(24,y-7,456,y+25);drawMenuRow(menuTextForSelection(previousSelection),row,0);row=menuRowForSelection(menuSelection);y=menuRowY(row);h.clearRect(24,y-7,456,y+25);drawMenuRow(menuTextForSelection(menuSelection),row,1)}function redrawBetValues(){h.clearRect(30,54,448,132).setColor(3).drawString(opponent+"'s Current Ante: "+ante,38,60).drawString("Your Current Ante: "+ante,38,86).drawString("Your Total Funds: "+funds,38,112)}function drawCurrentScreen(){if(screen===0)drawMainMenu();else if(screen===1)drawBetMenu();else if(screen===2)drawDeckMenu();else if(screen===3)drawResults();else drawRules()}function unloadSoundMenu(defragment){if(soundModule&&soundModule.remove)soundModule.remove();soundModule=0;if(defragment)E.defrag()}function onSoundMenuExit(){unloadSoundMenu(1);screen=0;menuSelection=3;attachMenuListeners();drawMainMenu()}function startSoundMenu(){let sourceCode,soundFactory;detachMenuListeners();try{sourceCode=fs.readFileSync(appPath+"CARAVAN_SOUND.MIN.JS");soundFactory=eval(sourceCode);sourceCode=0;soundModule=soundFactory({fs:fs,basePath:appPath,onBack:onSoundMenuExit});soundFactory=0}catch(error){sourceCode=0;soundFactory=0;soundModule=0;menuSelection=3;attachMenuListeners();drawMainMenu()}}function detachMenuListeners(){if(knob1Attached){Pip.removeListener("knob1",onKnob1);knob1Attached=0}if(knob2Attached){Pip.removeListener("knob2",onKnob2);knob2Attached=0}}function attachMenuListeners(){if(!knob1Attached){Pip.onExclusive("knob1",onKnob1);knob1Attached=1}if(!knob2Attached){try{Pip.onExclusive("knob2",onKnob2);knob2Attached=1}catch(error){if(knob1Attached){Pip.removeListener("knob1",onKnob1);knob1Attached=0}throw error}}}function unloadResults(defragment){if(resultsStartTimer){clearTimeout(resultsStartTimer);resultsStartTimer=0}if(resultsModule&&resultsModule.remove)resultsModule.remove();resultsModule=0;if(defragment)E.defrag()}function startResultsAnimation(){let sourceCode,resultsFactory;unloadResults(0);try{E.defrag()}catch(error){}try{sourceCode=fs.readFileSync(appPath+"CARAVAN_RESULTS.MIN.JS");resultsFactory=eval(sourceCode);sourceCode=0;resultsModule=resultsFactory({fs:fs,basePath:appPath,opponent:opponent,outcome:resultOutcome,delta:resultDelta,onComplete:function(){if(resultsModule&&resultsModule.remove)resultsModule.remove();resultsModule=0;try{E.defrag()}catch(error){}}});resultsFactory=0}catch(error){resultsModule=0;drawResultFallback()}}function beginResultsAfterGame(){resultsStartTimer=0;if(removed||screen!==3)return;try{E.defrag()}catch(error){}startResultsAnimation()}function startGame(){if(removed)return;unloadResults(0);unloadSoundMenu(0);detachMenuListeners();h.clear();api.onStartGame({ante:ante,funds:funds,opponent:opponent})}function unloadDemo(defragment){if(demoModule&&demoModule.remove)demoModule.remove();demoModule=0;if(defragment)E.defrag()}function onDemoExit(){unloadDemo(1);screen=0;menuSelection=1;attachMenuListeners();drawMainMenu()}function startDemo(){let sourceCode,demoFactory;detachMenuListeners();E.defrag();h.clear().setColor(3).setFontMonofonto16().setFontAlign(0,-1).drawString("LOADING DEMO...",240,146).setFontAlign(-1,-1);sourceCode=fs.readFileSync(appPath+"CARAVAN_DEMO.MIN.JS");demoFactory=eval(sourceCode);sourceCode=0;demoModule=demoFactory({fs:fs,basePath:appPath,onExit:onDemoExit});demoFactory=0}function exitHolotape(){try{Pip.changeMenu("MISC.JS")}catch(error){try{Pip.changeMenu()}catch(fallbackError){}}}function onKnob2(direction){if(screen!==1||!direction)return;ante+=direction>0?10:-10;if(ante<10)ante=10;if(ante>funds)ante=funds;Pip.playSound("SCROLL");redrawBetValues()}function onKnob1(direction){let optionCount;if(direction){const previousSelection=menuSelection;optionCount=screen===0?5:screen===1?4:screen===2?2:screen===3?2:1;menuSelection+=direction>0?1:-1;if(menuSelection<0)menuSelection=optionCount-1;if(menuSelection>=optionCount)menuSelection=0;Pip.playSound("SCROLL");if(optionCount>1)redrawMenuSelection(previousSelection);return}if(!(screen===0&&menuSelection===3)&&!(screen===2&&menuSelection===0)&&!(screen===3&&menuSelection===0)){Pip.playSound("SELECT")}if(screen===0){if(menuSelection===0){screen=1;menuSelection=0}else if(menuSelection===1){startDemo();return}else if(menuSelection===2){screen=4;menuSelection=0}else if(menuSelection===3){startSoundMenu();return}else{exitHolotape();return}}else if(screen===1){if(menuSelection===0){ante=Math.min(50,funds)}else if(menuSelection===1){ante+=10;if(ante>funds)ante=funds}else if(menuSelection===2){screen=2;menuSelection=0}else{screen=0;menuSelection=0}}else if(screen===2){if(menuSelection===0){startGame();return}screen=1;menuSelection=2}else if(screen===3){if(menuSelection===0){startGame();return}unloadResults(1);screen=0;menuSelection=0}else{screen=0;menuSelection=1}drawCurrentScreen()}function removeApp(){if(removed)return;removed=1;detachMenuListeners();if(demoModule&&demoModule.remove)demoModule.remove();demoModule=0;if(resultsModule&&resultsModule.remove)resultsModule.remove();resultsModule=0;if(soundModule&&soundModule.remove)soundModule.remove();soundModule=0;}attachMenuListeners();drawCurrentScreen();if(screen===3){if(resultsStartTimer)clearTimeout(resultsStartTimer);resultsStartTimer=setTimeout(beginResultsAfterGame,100)}return{id:"CARAVAN_MENU",remove:removeApp}});